": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "最不利原则忘记加1"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "和定最值忽略\"互不相等\"等约束条件"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "整数约束下直接用均值不等式，没有考虑整数解"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "最值问题是高频考点，最不利原则几乎每年必考。建议重点练习最不利原则和和定最值两类题型。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-最值问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "最值问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_extreme_value", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
